ALTER TABLE "node_attempts" ADD COLUMN "finish_continuation" jsonb;--> statement-breakpoint
ALTER TABLE "node_attempts" ADD CONSTRAINT "node_attempts_finish_continuation_check" CHECK ("node_attempts"."finish_continuation" IS NULL OR (jsonb_typeof("node_attempts"."finish_continuation") = 'object' AND "node_attempts"."finish_continuation"->'version' = '1'::jsonb AND jsonb_typeof("node_attempts"."finish_continuation"->'targetNodeId') IN ('string', 'null') AND jsonb_typeof("node_attempts"."finish_continuation"->'injectedVars') = 'object' AND ("node_attempts"."finish_continuation"->'sessionPolicy' = 'null'::jsonb OR "node_attempts"."finish_continuation"->>'sessionPolicy' IN ('resume', 'new_session')) AND jsonb_typeof("node_attempts"."finish_continuation"->'autoRetry') = 'boolean') IS TRUE);